require_once '../../config/database.php';require_once '../../config/helpers.php';require_role('admin');$id=(int)($_GET['id']??$_POST['id']??0);$stmt=mysqli_prepare($conn,'SELECT * FROM subjects WHERE id=?');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$subject=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if(!$subject){flash('Subject not found.','danger');header('Location: index.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code=strtoupper(trim($_POST['subject_code']??''));$name=trim($_POST['subject_name']??'');$units=(int)($_POST['units']??0);if($code===''||$name===''||$units<1||$units>30)$error='Enter a subject code, name, and unit count from 1 to 30.';else{$stmt=mysqli_prepare($conn,'UPDATE subjects SET subject_code=?,subject_name=?,units=? WHERE id=?');mysqli_stmt_bind_param($stmt,'ssii',$code,$name,$units,$id);if(mysqli_stmt_execute($stmt)){flash('Subject updated successfully.');header('Location: index.php');exit;}$error=mysqli_errno($conn)===1062?'That subject code already exists.':'Could not update this subject.';$subject=array_merge($subject,['subject_code'=>$code,'subject_name'=>$name,'units'=>$units]);}}
?>
